const $ = s => document.querySelector(s);
const state = {page:localStorage.getItem('zustore-page')||'home', category:'All', query:'', user:null, token:localStorage.getItem('zustore-token')||'', apps:[], categories:[], library:[], reviews:[], messages:[], settings:{}, adminTab:'overview', messageTab:'inbox', adminData:null};
const iconPaths = {
  All:'M12 3.5 14 9l5.5 2-5.5 2-2 5.5L10 13l-5.5-2L10 9z',
  Games:'M7 8h10a4 4 0 0 1 3.9 4.9l-.7 3a2.5 2.5 0 0 1-4.3 1.1L14 15h-4l-1.9 2a2.5 2.5 0 0 1-4.3-1.1l-.7-3A4 4 0 0 1 7 8Z M7 10.5v4m-2-2h4m7-.5h.1m2 2h.1',
  Internet:'M3.5 12a8.5 8.5 0 1 0 17 0a8.5 8.5 0 1 0-17 0 M3.8 12h16.4 M12 3.5c2.3 2.2 3.3 5 3.3 8.5s-1 6.3-3.3 8.5c-2.3-2.2-3.3-5-3.3-8.5s1-6.3 3.3-8.5Z',
  System:'M5 4v16m7-16v16m7-16v16 M3 8h4m3 7h4m3-5h4',
  Utility:'M14.5 6a5 5 0 0 0-6.2 6.2L3.5 17l3.5 3.5 4.8-4.8A5 5 0 0 0 18 9.5l-3.2 3.2-3.5-3.5z',
  Multimedia:'M4 5.5h16v13H4z M10 9v6l5-3z',
  Privacy:'M12 3 19 6v5c0 4.7-3 8-7 10-4-2-7-5.3-7-10V6z M9 12l2 2 4-4',
  Reading:'M3.5 5.5c3-1.2 5.8-.8 8.5 1.2v13c-2.7-2-5.5-2.4-8.5-1.2z M20.5 5.5c-3-1.2-5.8-.8-8.5 1.2v13c2.7-2 5.5-2.4 8.5-1.2z',
  Education:'M3 9.5 12 4l9 5.5-9 5.5z M6.5 12v4c3.3 2.8 7.7 2.8 11 0v-4 M21 10v6',
  Health:'M20 8.5c0 4.1-8 10-8 10s-8-5.9-8-10a4 4 0 0 1 7.5-2 4 4 0 0 1 8.5 2Z',
  Finance:'M4 8h16v11H4z M4 8l8-4 8 4 M8 12h8m-6 3h4',
  Communication:'M4 5.5h16v12H9l-5 3z M8 10h8m-8 4h5',
  Note:'M6 3.5h12v17H6z M9 8h6m-6 4h6m-6 4h4',
  Graphics:'M4 4h16v16H4z M8 16l3.2-4 2.4 2.5 2-2L20 17 M8.5 8.5h.1',
  Tools:'M14.5 6a5 5 0 0 0-6.2 6.2L3.5 17l3.5 3.5 4.8-4.8A5 5 0 0 0 18 9.5l-3.2 3.2-3.5-3.5z'
};
const icons = Object.fromEntries(Object.keys(iconPaths).map(key=>[key,`<svg width="21" height="21" viewBox="0 0 24 24" aria-hidden="true" style="display:block;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round"><path d="${iconPaths[key]}"/></svg>`]));
const safe = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api = async (url, options={}) => { const headers={...(options.headers||{})}; if(state.token)headers.Authorization=`Bearer ${state.token}`; if(options.body && !(options.body instanceof Blob))headers['Content-Type']='application/json'; const response=await fetch(url,{...options,headers}); const body=await response.json().catch(()=>({})); if(!response.ok)throw new Error(body.error||'Something went wrong.');return body; };
async function refresh(){const d=await api('/api/bootstrap');state.user=d.user;if(!d.user&&state.token){state.token='';localStorage.removeItem('zustore-token')}state.settings=d.settings;state.categories=d.categories;state.apps=d.apps;state.library=d.library;state.reviews=d.reviews;state.messages=d.messages;$('#avatarText').textContent=state.user?.name?.[0]?.toUpperCase()||'Z';}
const visibleApps=()=>state.apps.filter(a=>a.status==='published'&&(state.category==='All'||a.category===state.category)&&(!state.query||`${a.name} ${a.developer} ${a.category} ${a.subcategory}`.toLowerCase().includes(state.query.toLowerCase())));
function icon(a, cls='app-icon'){const key=({'👹':'Games','▶':'Multimedia','▤':'Utility','◈':'Privacy','🎲':'Games','▣':'Reading','＋':'Education','◉':'Multimedia','🧰':'Tools'})[a.icon]||a.category||'All';const art=a.iconUrl?`<img src="${safe(a.iconUrl)}" alt="" loading="lazy">`:(icons[key]||icons.All);return `<span class="${cls} tone-${safe(a.color||'blue')} ${a.iconUrl?'has-image':''}">${art}</span>`}
function screenshotsMarkup(a){const shots=a.screenshots?.length?a.screenshots:['Home screen','Explore','Settings'];return shots.map((shot,i)=>{const label=typeof shot==='string'?shot:(shot.name||'Screenshot');return `<div class="screen-preview">${typeof shot==='object'&&shot.url?`<img src="${safe(shot.url)}" alt="${safe(label)}" style="width:100%;height:100%;object-fit:cover;border-radius:11px"><span>${safe(label)}</span>`:`<div class="screen-mock" style="background:linear-gradient(150deg,${['#ffc8a7,#f18ea3','#a9d9e8,#8fd6c7','#ddd1ff,#9ac6e4'][i%3]})"></div><span>${safe(label)}</span>`}</div>`}).join('')}
function appCard(a){return `<article class="app-card" data-app="${safe(a.id)}">${a.badge?`<span class="app-badge ${a.featured?'featured':a.badge==='NEW'?'new':''}">${safe(a.badge)}</span>`:''}<div class="app-row">${icon(a)}<div class="app-copy"><div class="app-name">${safe(a.name)}</div><div class="app-developer">${safe(a.developer)}</div></div></div><div class="app-meta"><span>${safe(a.subcategory||a.category)}</span><span class="rating">${a.rating?`★ ${Number(a.rating).toFixed(1)}`:'New'}</span></div></article>`}
function section(title, subtitle, apps, link='apps'){return `<section class="section"><div class="section-head"><div><h2 class="section-title">${title}</h2>${subtitle?`<p class="section-sub">${subtitle}</p>`:''}</div><button class="text-button" data-go="${link}">See all&nbsp; →</button></div><div class="app-grid">${apps.length?apps.map(appCard).join(''):`<div class="empty-state" style="grid-column:1/-1;padding:22px"><h3>Nothing here yet</h3><p>Check back soon for new additions.</p></div>`}</div></section>`}
function categories(){const list=state.categories.filter(c=>c!=='All').slice(0,8);return `<div class="categories">${list.map(c=>`<button class="category-card ${state.category===c?'selected':''}" data-category="${safe(c)}"><span class="category-icon">${icons[c]||icons.All}</span><span>${safe(c)}</span></button>`).join('')}</div>`}
function homePage(){const apps=visibleApps();const fresh=apps.filter(a=>['Today','Yesterday','2 days ago'].includes(a.updated));const newApps=(fresh.length?fresh:apps).slice(0,6);const suggested=apps.slice().sort((a,b)=>(Number(b.rating)||0)-(Number(a.rating)||0)).slice(0,6);let viewed=[];try{viewed=(JSON.parse(localStorage.getItem('zustore-recent-views')||'[]')).map(id=>state.apps.find(a=>a.id===id)).filter(Boolean)}catch{}const related=viewed.length?apps.filter(a=>a.id!==viewed[0].id&&a.category===viewed[0].category).concat(apps.filter(a=>a.id!==viewed[0].id&&a.category!==viewed[0].category)):apps.slice().sort((a,b)=>(Number(b.downloads)||0)-(Number(a.downloads)||0));const relatedTitle=viewed.length?`Because you looked at ${safe(viewed[0].name)}`:'Popular on ZUStore';const recentCard=a=>{const shot=a.screenshots?.find(x=>typeof x==='object'&&x.url);return `<article class="new-app-card" data-app="${safe(a.id)}"><div class="new-card-copy"><div class="new-app-top">${icon(a,'new-app-icon')}<span class="new-pill">${safe(a.badge||'NEW')}</span></div><h3>${safe(a.name)}</h3><p>${safe(a.subcategory||a.category)} · ${safe(a.size)}</p><span class="added-pill">Added ${safe(a.updated==='Today'?'today':a.updated==='Yesterday'?'yesterday':'recently')}</span></div><div class="new-phone"><div class="phone-speaker"></div>${shot?`<img src="${safe(shot.url)}" alt="${safe(shot.name||a.name)} preview">`:`<div class="phone-screen"><div class="phone-brand">${safe(a.name)}</div>${icon(a,'phone-app-art')}<b>${safe(a.subcategory||a.category)}</b><span>Explore the app</span><i></i></div>`}</div></article>`};return `<div class="store-home"><section class="home-categories" aria-label="Browse categories">${state.categories.filter(c=>c!=='All').slice(0,8).map(c=>{const count=state.apps.filter(a=>a.category===c&&a.status==='published').length;return `<button class="home-category" data-category="${safe(c)}"><span class="home-category-icon">${icons[c]||icons.All}</span><b>${safe(c)}</b><small>${count} ${count===1?'app':'apps'}</small></button>`}).join('')}</section><section class="store-section new-apps-section"><div class="store-section-head"><div><h2>New on ZUStore</h2><p>Just added, newest first</p></div><button class="carousel-next" data-carousel-next="newAppsTrack" aria-label="Next apps">→</button></div><div class="new-apps-track" id="newAppsTrack">${newApps.map(recentCard).join('')}</div></section><section class="store-section"><div class="store-section-head"><div><h2>Suggested for you</h2><p>Picked from the ZUStore community</p></div><button class="text-link" data-go="apps">See all →</button></div><div class="suggested-track">${suggested.map(a=>`<article class="suggested-app-card" data-app="${safe(a.id)}">${icon(a,'suggested-icon')}<h3>${safe(a.name)}</h3><span>${safe(a.featured?'Picked for you':`More ${a.category}`)}</span></article>`).join('')}</div></section><section class="store-section"><div class="store-section-head"><div><h2>${relatedTitle}</h2><p>${viewed.length?'More apps you may like':'Popular picks from the store'}</p></div><button class="text-link" data-go="apps">See all →</button></div><div class="suggested-track related-track">${related.slice(0,6).map(a=>`<article class="suggested-app-card related-app-card" data-app="${safe(a.id)}">${icon(a,'suggested-icon')}<h3>${safe(a.name)}</h3><span>${safe(a.subcategory||a.category)} · ${safe(a.size)}</span></article>`).join('')}</div></section><section class="store-section browse-more"><div class="store-section-head"><div><h2>Browse all apps</h2><p>Find games, tools and more</p></div><button class="text-link" data-go="apps">Explore →</button></div><div class="browse-chips">${state.categories.filter(c=>c!=='All').map(c=>`<button class="filter-chip" data-category="${safe(c)}">${safe(c)} <span>${state.apps.filter(a=>a.category===c&&a.status==='published').length}</span></button>`).join('')}</div></section></div>`}
function appsPage(){let apps=visibleApps();return `<header class="page-head"><h1>Explore apps</h1><p>Find something useful, playful or just a little different.</p></header><div class="filter-row">${['All',...state.categories.filter(x=>x!=='All')].map(c=>`<button class="filter-chip ${state.category===c?'active':''}" data-category="${safe(c)}">${safe(c)}</button>`).join('')}</div><div class="page-grid"><div class="app-grid">${apps.length?apps.map(appCard).join(''):`<div class="empty-state" style="grid-column:1/-1"><div class="empty-icon">⌕</div><h3>No apps found</h3><p>Try a different search or category.</p><button class="small-button" data-clear>Clear filters</button></div>`}</div><aside class="side-card"><h3>Trending categories</h3>${state.categories.filter(x=>x!=='All').slice(0,7).map((c,i)=>`<div class="side-link" data-category="${safe(c)}"><span>${icons[c]||icons.All} &nbsp;${safe(c)}</span><b>${(apps.filter(a=>a.category===c).length*24+39).toLocaleString()}</b></div>`).join('')}<div class="side-link" data-go="profile"><span>Are you a developer?</span><b>Submit&nbsp; →</b></div></aside></div>`}
function libraryPage(){const apps=state.library.map(id=>state.apps.find(a=>a.id===id)).filter(Boolean);return `<header class="page-head"><h1>My Library</h1><p>Your downloads and saved apps, all in one place.</p></header><div class="filter-row"><button class="filter-chip active">All ${apps.length}</button><button class="filter-chip">ZUStore ${apps.length}</button><button class="filter-chip">Ready to install ${apps.filter(a=>a.apkUrl).length}</button></div>${apps.length?apps.map(a=>`<div class="library-card">${icon(a)}<div class="library-info"><b>${safe(a.name)}</b><span>${safe(a.developer)} · ${safe(a.size)}</span><div class="install-state">${a.apkUrl?'Ready to install':'Saved to your library'}</div></div><div class="library-actions">${a.apkUrl?`<a class="small-button" href="${safe(a.apkUrl)}" download>Install</a>`:`<button class="small-button" data-app="${safe(a.id)}">View</button>`}<button class="ghost-button" data-remove="${safe(a.id)}">Remove</button></div></div>`).join(''):`<div class="empty-state"><div class="empty-icon">⇩</div><h3>Your library is waiting</h3><p>Save an app from the store and it will be easy to find here later.</p><button class="small-button" data-go="apps">Explore apps</button></div>`}`}
function messagesPage(){const items=state.messageTab==='developers'?state.messages.filter(m=>m.kind==='developer'):state.messageTab==='global'?state.messages.filter(m=>m.kind!=='developer'):state.messages;return `<header class="page-head"><h1>Messages</h1><p>Keep up with the store and its community.</p></header><div class="message-tabs"><button class="${state.messageTab==='inbox'?'active':''}" data-msg-tab="inbox">Inbox</button><button class="${state.messageTab==='global'?'active':''}" data-msg-tab="global">Global</button><button class="${state.messageTab==='developers'?'active':''}" data-msg-tab="developers">Developers</button></div><div class="message-list">${items.slice().reverse().map(m=>`<article class="message-card"><div class="message-avatar">${safe(m.from[0])}</div><div class="message-main"><header><b>${safe(m.from)}${m.kind==='announcement'?'　✦':''}</b><time>${safe(m.date)}</time></header><p>${safe(m.text)}</p></div></article>`).join('')||`<div class="empty-state"><div class="empty-icon">▤</div><h3>No messages yet</h3><p>Updates and community notes will appear here.</p></div>`}</div>${state.user?`<form id="messageForm" class="message-card" style="align-items:center"><div class="message-avatar">${safe(state.user.name[0])}</div><input name="text" placeholder="Share something with the community…" maxlength="500" style="flex:1;border:0;outline:0;font-size:11px"><button class="round-arrow" aria-label="Send">➤</button></form>`:''}`}
function profilePage(){const u=state.user;if(!u)return `<header class="page-head"><h1>Your account</h1><p>Sign in to keep your apps, reviews and developer profile together.</p></header><div class="empty-state"><div class="empty-icon">◉</div><h3>Welcome to ZUStore</h3><p>Create a free profile to save apps, talk with developers and publish your own work.</p><button class="small-button" data-auth="register">Create account</button>&nbsp;<button class="ghost-button" data-auth="login">Sign in</button></div>`;const count=state.apps.filter(a=>a.developer===u.name).length;return `<header class="page-head"><h1>Your account</h1><p>Profile, downloads and developer tools.</p></header><section class="profile-card"><div class="profile-cover"></div><div class="profile-avatar">${safe(u.name[0].toUpperCase())}</div><h2>${safe(u.name)}</h2><p>${safe(u.email)}</p><span class="app-badge" style="position:static;display:inline-block;margin-top:8px">${safe(u.role.toUpperCase())}</span><div class="profile-stats"><div><b>${state.library.length}</b><span>Apps</span></div><div><b>${count}</b><span>Published</span></div><div><b>${state.reviews.filter(r=>r.user===u.name).length}</b><span>Reviews</span></div></div>${u.role==='developer'||u.role==='admin'?`<div class="dev-dashboard"><div class="dev-dashboard-head"><b>Developer dashboard</b><button class="text-button" data-submit-app>＋ New app</button></div><div class="dash-stats"><div class="dash-stat"><b>${state.apps.filter(a=>a.developer===u.name&&a.status==='published').length}</b><span>LIVE</span></div><div class="dash-stat"><b>${state.apps.filter(a=>a.developer===u.name&&a.status==='pending').length}</b><span>IN REVIEW</span></div><div class="dash-stat"><b>${state.apps.filter(a=>a.developer===u.name&&a.status==='rejected').length}</b><span>NEEDS YOU</span></div></div><p style="font-size:9px;color:#8d9ca2;margin:6px 0 0">Submit apps for review. Approved apps appear in the public catalogue.</p></div>`:`<div class="dev-dashboard"><div class="dev-dashboard-head"><b>Developer dashboard</b><button class="text-button" data-submit-app>＋ New app</button></div><p style="font-size:9px;color:#8d9ca2;margin:9px 0 0">Have an app to share? Create a developer listing and send it for review.</p></div>`}<div class="profile-menu"><button data-go="library"><b>⇩ &nbsp;Downloads & storage</b><span>Your saved apps and installs</span></button><button data-go="messages"><b>▤ &nbsp;Notifications</b><span>Store messages and updates</span></button><button data-settings><b>⚙ &nbsp;System</b><span>Appearance and preferences</span></button><button data-admin><b>✦ &nbsp;Admin console</b><span>Manage your store</span></button></div><button class="ghost-button" id="logoutBtn" style="margin-top:14px">Sign out</button></section>`}
function render(){const pages={home:homePage,apps:appsPage,library:libraryPage,messages:messagesPage,profile:profilePage,admin:adminPage};$('#mainContent').innerHTML=(pages[state.page]||homePage)();localStorage.setItem('zustore-page',state.page);document.querySelectorAll('#bottomNav button').forEach(b=>b.classList.toggle('active',b.dataset.page==='games'?state.page==='apps'&&state.category==='Games':b.dataset.page==='apps'?state.page==='home'||state.page==='apps'&&state.category!=='Games':b.dataset.page===state.page));$('#searchInput').value=state.query;$('#clearSearch').style.display=state.query?'block':'';}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2600)}
function openModal(html){$('#modal').innerHTML=`<button class="modal-close" data-close aria-label="Close">×</button>${html}`;$('#modalBackdrop').classList.add('open');document.body.style.overflow='hidden'}
function closeModal(){ $('#modalBackdrop').classList.remove('open');document.body.style.overflow='';if(location.hash.startsWith('#app/'))history.replaceState(null,'',location.pathname); }
function authModal(mode='login'){const register=mode==='register';openModal(`<h2>${register?'Create your account':'Welcome back'}</h2><p class="modal-lead">${register?'Join the ZUStore community in a few seconds.':'Sign in to your ZUStore account.'}</p><form id="authForm" class="modal-form">${register?`<div class="field"><label>Your name</label><input name="name" required autocomplete="name" placeholder="What should we call you?"></div>`:''}<div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div><div class="field"><label>Password</label><input name="password" type="password" minlength="${register?8:1}" required autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'At least 8 characters':'Your password'}"></div><button class="modal-submit">${register?'Create account':'Sign in'}</button></form><p class="modal-lead" style="text-align:center;margin:14px 0 0">${register?'Already have an account?':'New to ZUStore?'} <button class="text-button" data-auth="${register?'login':'register'}">${register?'Sign in':'Create an account'}</button></p>`)}
async function uploadFile(file,onProgress){if(!file)return '';return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/upload');xhr.setRequestHeader('Authorization',`Bearer ${state.token}`);xhr.setRequestHeader('X-Filename',encodeURIComponent(file.name));xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.upload.onprogress=e=>{if(e.lengthComputable&&onProgress)onProgress(e.loaded,e.total)};xhr.onload=()=>{let data={};try{data=JSON.parse(xhr.responseText)}catch{}if(xhr.status<200||xhr.status>=300)reject(new Error(data.error||'Upload failed'));else resolve(data.url)};xhr.onerror=()=>reject(new Error('Upload failed. Check your connection and try again.'));xhr.onabort=()=>reject(new Error('Upload cancelled.'));xhr.send(file)})}
function formatFileSize(bytes){if(!bytes)return '0 B';const units=['B','KB','MB','GB'];let n=bytes,i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return `${n.toFixed(i?1:0)} ${units[i]}`}
function appSubmitModal(){if(!state.user)return authModal('login');openModal(`<h2>Share a new app</h2><p class="modal-lead">Add a real app package and clear screenshots. New submissions are reviewed before they appear in the store.</p><form id="appSubmitForm" class="modal-form"><div class="form-row"><div class="field"><label>App name</label><input name="name" required maxlength="80" placeholder="e.g. My Great App"></div><div class="field"><label>Category</label><select name="category">${state.categories.filter(c=>c!=='All').map(c=>`<option>${safe(c)}</option>`).join('')}</select></div></div><div class="form-row"><div class="field"><label>Version</label><input name="version" required value="1.0.0"></div><div class="field"><label>App size</label><input name="size" placeholder="e.g. 24 MB"></div></div><div class="field"><label>Short description</label><textarea name="description" required maxlength="1500" placeholder="What makes your app useful or fun?"></textarea></div><div class="form-row"><div class="field"><label>App icon image</label><input name="iconFile" type="file" accept="image/png,image/jpeg,image/webp"><span class="form-hint">Square PNG, JPG or WEBP.</span></div><div class="field"><label>APK file</label><input name="apk" type="file" accept=".apk,application/vnd.android.package-archive"><span class="form-hint">APK upload is optional for review.</span></div></div><div class="field"><label>Screenshots</label><input name="screenshots" type="file" accept="image/png,image/jpeg,image/webp" multiple><span class="form-hint">Show people what the app looks like.</span></div><button class="modal-submit">Submit for review</button></form>`)}
function adminAppModal(){openModal(`<span class="eyebrow admin-eyebrow">ADMIN · STORE CATALOGUE</span><h2 style="margin-top:8px">Add a new app</h2><p class="modal-lead">Create a complete store listing with app details, screenshots and a downloadable APK.</p><form id="adminAppForm" class="modal-form admin-app-form"><section class="admin-form-section"><h3>App information</h3><div class="form-row"><div class="field"><label>App name *</label><input name="name" required maxlength="80" placeholder="e.g. My Great App"></div><div class="field"><label>Developer / publisher</label><input name="developer" maxlength="80" value="ZUStore" placeholder="Publisher name"></div></div><div class="form-row"><div class="field"><label>Category *</label><select name="category" required>${state.categories.filter(c=>c!=='All').map(c=>`<option>${safe(c)}</option>`).join('')}</select></div><div class="field"><label>Subcategory</label><input name="subcategory" maxlength="48" placeholder="e.g. Photo editor"></div></div><div class="form-row"><div class="field"><label>Version name *</label><input name="version" required maxlength="24" value="1.0.0" placeholder="1.0.0"></div><div class="field"><label>Version code</label><input name="versionCode" type="number" min="1" step="1" placeholder="e.g. 12"></div></div><div class="form-row"><div class="field"><label>Android package ID</label><input name="packageName" maxlength="160" placeholder="com.example.app"></div><div class="field"><label>Minimum Android</label><input name="minAndroid" maxlength="32" placeholder="e.g. Android 8.0+"></div></div><div class="field"><label>Tags</label><input name="tags" maxlength="240" placeholder="games, offline, editor"><span class="form-hint">Separate tags with commas.</span></div></section><section class="admin-form-section"><h3>Store description</h3><div class="field"><label>Short description *</label><textarea name="description" required maxlength="180" placeholder="One sentence shown on app cards"></textarea><span class="form-hint"><span data-char-count="description">0</span>/180</span></div><div class="field"><label>Full description</label><textarea name="fullDescription" maxlength="5000" placeholder="Explain features, how the app works, and what users can expect"></textarea></div><div class="field"><label>What’s new in this version</label><textarea name="whatsNew" maxlength="1200" placeholder="Bug fixes, improvements and new features"></textarea></div></section><section class="admin-form-section"><h3>App files and screenshots</h3><div class="admin-asset-grid"><div class="field"><label>App icon *</label><label class="upload-drop icon-drop" for="adminIconFile"><input id="adminIconFile" name="iconFile" type="file" accept="image/png,image/jpeg,image/webp" required><span class="upload-drop-icon">▣</span><b>Choose icon image</b><small>PNG, JPG or WEBP · square · up to 12 MB</small><span id="adminIconPreview" class="asset-preview"></span></label></div><div class="field"><label>APK package *</label><label class="upload-drop apk-drop" for="adminApkFile"><input id="adminApkFile" name="apk" type="file" accept=".apk,application/vnd.android.package-archive" required><span class="upload-drop-icon">↓</span><b>Choose APK file</b><small>Android package · up to 350 MB</small><span id="adminApkPreview" class="apk-preview">No APK selected</span></label></div></div><div class="field"><label>Screenshots</label><label class="upload-drop screenshots-drop" for="adminScreenshots"><input id="adminScreenshots" name="screenshots" type="file" accept="image/png,image/jpeg,image/webp" multiple><span class="upload-drop-icon">▧</span><b>Select screenshots</b><small>Up to 8 images · PNG, JPG or WEBP · up to 12 MB each</small></label><div id="adminScreenshotPreviews" class="admin-screenshot-previews"></div></div></section><section class="admin-form-section"><h3>Store settings</h3><div class="form-row"><div class="field"><label>Content rating</label><select name="contentRating"><option>Everyone</option><option>Everyone 10+</option><option>Teen</option><option>Mature 17+</option></select></div><div class="field"><label>Badge</label><input name="badge" maxlength="20" placeholder="NEW, FEATURED, OPEN SOURCE"></div></div><div class="form-row"><div class="field"><label>Website</label><input name="websiteUrl" type="url" placeholder="https://example.com"></div><div class="field"><label>Support email</label><input name="supportEmail" type="email" placeholder="support@example.com"></div></div><div class="form-row"><div class="field"><label>Privacy policy URL</label><input name="privacyUrl" type="url" placeholder="https://example.com/privacy"></div><div class="field"><label>Download size</label><input name="size" id="adminAppSize" placeholder="Auto-filled from APK"></div></div><div class="form-row"><div class="field"><label>Visibility</label><select name="status"><option value="published">Publish now</option><option value="pending">Save as pending review</option></select></div><label class="admin-check-field"><input name="featured" type="checkbox"><span><b>Feature this app</b><small>Show it in the store spotlight</small></span></label></div></section><div id="adminUploadProgress" class="upload-progress" hidden><div><b>Uploading app files…</b><span id="adminUploadStatus">Preparing upload</span></div><div class="upload-progress-track"><i id="adminUploadBar"></i></div></div><button class="modal-submit" id="adminAppSubmit">Upload app and publish</button><p class="form-hint admin-form-footnote">You can choose “Save as pending review” to keep the listing hidden until it is ready.</p></form>`)}
function detailModal(id){const a=state.apps.find(x=>x.id===id);if(!a)return;history.replaceState(null,'',`#app/${encodeURIComponent(id)}`);const reviews=state.reviews.filter(r=>r.appId===a.id);const hasApk=!!a.apkUrl;try{const recent=JSON.parse(localStorage.getItem('zustore-recent-views')||'[]').filter(x=>x!==id);recent.unshift(id);localStorage.setItem('zustore-recent-views',JSON.stringify(recent.slice(0,8)))}catch{}openModal(`<div class="detail-hero"><div class="detail-head">${icon(a,'detail-icon')}<div><div class="detail-title">${safe(a.name)}</div><div class="detail-sub">${safe(a.developer)} · ${safe(a.category)}</div><div class="detail-rating">${a.rating?`★ ${Number(a.rating).toFixed(1)}　${a.ratingCount.toLocaleString()} reviews`:'✦ New to ZUStore'}</div></div></div><div class="detail-actions">${hasApk?`<button class="primary-btn download-cta" data-install="${safe(a.id)}" data-apk-url="${safe(a.apkUrl)}"><span class="button-icon">↓</span><span>Download APK<small>${safe(a.size)} · v${safe(a.version)}</small></span></button>`:`<button class="primary-btn download-cta is-disabled" disabled><span class="button-icon">↓</span><span>APK not uploaded<small>This listing has no install file yet</small></span></button>`}<button class="ghost-button save-cta" data-save-library="${safe(a.id)}">${state.library.includes(a.id)?'✓ Saved':'＋ Save to library'}</button><button class="ghost-button share-cta" data-share="${safe(a.id)}" aria-label="Share app">↗</button></div></div><div class="detail-meta"><div><b>${a.rating?Number(a.rating).toFixed(1)+' ★':'New'}</b><span>Rating</span></div><div><b>${safe(a.size)}</b><span>Download size</span></div><div><b>${safe(a.version)}</b><span>Latest version</span></div></div><section class="detail-info-card"><h3>About this app</h3><p class="detail-copy">${safe(a.fullDescription||a.description)}</p></section>${a.whatsNew?`<section class="detail-info-card"><h3>What’s new</h3><p class="detail-copy">${safe(a.whatsNew)}</p></section>`:` `}<section class="detail-info-card build-info"><h3>Versions & builds <span class="detail-tag">${hasApk?'DIRECT DOWNLOAD':'COMING SOON'}</span></h3><div class="build-row"><span class="build-platform">A</span><div><b>Android · v${safe(a.version)}</b><small>${hasApk?safe(a.apkName||'APK package ready'):'Developer has not uploaded an APK yet'}</small></div><strong>${safe(a.size)}</strong></div>${hasApk?`<button class="build-download" data-install="${safe(a.id)}" data-apk-url="${safe(a.apkUrl)}">↓ &nbsp; Download v${safe(a.version)}</button>`:''}</section>${a.packageName||a.minAndroid||a.contentRating||a.versionCode?`<section class="detail-info-card"><h3>App details</h3><div class="app-spec-grid">${a.packageName?`<div><span>Package</span><b>${safe(a.packageName)}</b></div>`:''}${a.minAndroid?`<div><span>Requires Android</span><b>${safe(a.minAndroid)}</b></div>`:''}${a.versionCode?`<div><span>Version code</span><b>${safe(a.versionCode)}</b></div>`:''}${a.contentRating?`<div><span>Content rating</span><b>${safe(a.contentRating)}</b></div>`:''}</div></section>`:''}${a.websiteUrl||a.privacyUrl||a.supportEmail||a.tags?.length?`<section class="detail-info-card"><h3>More information</h3><div class="app-links">${a.websiteUrl?`<a href="${safe(a.websiteUrl)}" target="_blank" rel="noopener">App website ↗</a>`:''}${a.privacyUrl?`<a href="${safe(a.privacyUrl)}" target="_blank" rel="noopener">Privacy policy ↗</a>`:''}${a.supportEmail?`<a href="mailto:${safe(a.supportEmail)}">Contact support</a>`:''}</div>${a.tags?.length?`<div class="app-tag-list">${a.tags.map(tag=>`<span>${safe(tag)}</span>`).join()}</div>`:''}</section>`:''}<section class="detail-info-card"><div class="detail-section-head"><h3>Screenshots</h3><span class="detail-tag">PREVIEW</span></div><div class="screens-row">${screenshotsMarkup(a)}</div></section><section class="detail-info-card"><div class="detail-section-head"><h3>Reviews</h3><span class="form-hint">${reviews.length} reviews</span></div>${reviews.length?reviews.slice(0,3).map(r=>`<div class="review"><div class="review-head"><b>${safe(r.user)}</b><span>${'★'.repeat(r.rating)}</span></div><p>${safe(r.text)}</p></div>`).join(''):`<p class="detail-copy">No reviews yet. Be the first to share feedback.</p>`}${state.user?`<form id="reviewForm" class="modal-form" data-review-app-id="${safe(a.id)}" style="margin-top:12px"><div class="form-row"><div class="field"><label>Your rating</label><select name="rating"><option value="5">★★★★★</option><option value="4">★★★★☆</option><option value="3">★★★☆☆</option><option value="2">★★☆☆☆</option><option value="1">★☆☆☆☆</option></select></div><div class="field"><label>Review</label><input name="text" maxlength="500" placeholder="Tell others what you think"></div></div><button class="ghost-button">Post review</button></form>`:''}</section>`)}

function adminPage(){if(!state.user||state.user.role!=='admin')return `<div class="empty-state"><div class="empty-icon">✦</div><h3>Admin sign in</h3><p>The admin console is reserved for authorized store managers.</p><button class="small-button" data-auth="login">Sign in as admin</button></div>`;return `<div class="admin-shell"><aside class="admin-side"><div class="admin-label">ZUStore management</div><nav class="admin-nav">${[['overview',icons.All,'Overview'],['apps',icons.Multimedia,'App submissions'],['users',icons.Communication,'Users'],['categories',icons.Internet,'Categories'],['reviews',icons.Health,'Reviews'],['messages',icons.Communication,'Announcements'],['settings',icons.System,'Settings']].map(([key,ico,label])=>`<button class="${state.adminTab===key?'active':''}" data-admin-tab="${key}"><span>${ico}</span>${label}${key==='apps'&&state.adminData?.apps.filter(a=>a.status==='pending').length?` <b style="float:right;color:#d59731">${state.adminData.apps.filter(a=>a.status==='pending').length}</b>`:''}</button>`).join('')}</nav><div class="admin-side-foot">Signed in as ${safe(state.user.name)}<br><a href="#profile" style="color:#12a7ad;text-decoration:none">Back to store ↗</a></div></aside><section class="admin-main">${renderAdminTab()}</section></div>`}
function adminHeading(title,sub,action=''){return `<div class="admin-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function metric(label,value,caption){return `<div class="metric-card"><span>${label}</span><b>${value}</b><i>${caption}</i></div>`}
function renderAdminTab(){const d=state.adminData||{apps:state.apps,users:[],reviews:state.reviews,messages:state.messages,categories:state.categories,settings:state.settings,downloads:state.library.length};const pending=d.apps.filter(a=>a.status==='pending');switch(state.adminTab){case'overview':return `${adminHeading('Overview','Your store at a glance.',`<button class="small-button" data-refresh-admin>↻ &nbsp; Refresh</button>`)}<div class="admin-cards">${metric('TOTAL USERS',d.users.length,'Community members')}${metric('PUBLISHED APPS',d.apps.filter(a=>a.status==='published').length,'Live in the store')}${metric('PENDING REVIEW',pending.length,'Waiting for a decision')}${metric('LIBRARY SAVES',d.downloads,'Across all users')}</div><div class="admin-panel"><div class="admin-toolbar"><h2>Needs your attention</h2><button class="text-button" data-admin-tab="apps">View all&nbsp; →</button></div>${pending.length?`<table class="admin-table"><thead><tr><th>App</th><th>Developer</th><th>Category</th><th>Submitted</th><th>Action</th></tr></thead><tbody>${pending.slice(0,5).map(a=>appTableRow(a,true)).join('')}</tbody></table>`:`<div class="admin-empty">All caught up. There are no apps waiting for review.</div>`}</div><div class="admin-panel"><h2>Recent community reviews</h2>${d.reviews.slice(-4).reverse().map(r=>`<div class="review"><div class="review-head"><b>${safe(r.user)} on ${safe(d.apps.find(a=>a.id===r.appId)?.name||'App')}</b><span>${'★'.repeat(r.rating)}</span></div><p>${safe(r.text)}</p></div>`).join('')||'<div class="admin-empty">No reviews yet.</div>'}</div>`;
case'apps':return `${adminHeading('App submissions','Upload APKs, manage listings and review developer submissions.',`<button class="small-button" data-admin-add-app>＋ Add app</button>`)}<div class="upload-guide"><span class="guide-icon">${icons.Multimedia}</span><div><b>Add a downloadable app</b><p>Tap <strong>＋ Add app</strong>, choose its APK, icon and details, then select <strong>Publish now</strong>. Published apps immediately show a Download APK button.</p></div></div>${d.apps.length?`<div class="admin-panel"><div class="admin-toolbar"><h2>All apps · ${d.apps.length}</h2><select class="admin-search" id="appStatusFilter"><option value="all">All statuses</option><option value="pending">Pending</option><option value="published">Published</option><option value="rejected">Needs changes</option></select></div><table class="admin-table"><thead><tr><th>App</th><th>Developer</th><th>Status</th><th>Downloads</th><th>Actions</th></tr></thead><tbody>${d.apps.map(a=>appTableRow(a,a.status==='pending')).join('')}</tbody></table></div>`:`<div class="admin-empty">No apps found.</div>`}`;
case'users':return `${adminHeading('Users','Manage accounts and developer access.')}<div class="admin-panel"><div class="admin-toolbar"><h2>Community · ${d.users.length}</h2><input class="admin-search" id="userSearch" placeholder="Search users"></div><table class="admin-table"><thead><tr><th>User</th><th>Role</th><th>Joined</th><th>Status</th><th>Action</th></tr></thead><tbody>${d.users.map(u=>`<tr data-user-row="${safe((u.name+' '+u.email).toLowerCase())}"><td><div class="table-title"><span class="mini-icon tone-mint">${safe(u.name[0])}</span><div>${safe(u.name)}<br><span style="color:#96a3a7;font-weight:400">${safe(u.email)}</span></div></div></td><td><select class="admin-search" data-user-role="${safe(u.id)}"><option ${u.role==='user'?'selected':''}>user</option><option ${u.role==='developer'?'selected':''}>developer</option><option ${u.role==='admin'?'selected':''}>admin</option></select></td><td>${safe(u.joined)}</td><td><span class="status-pill ${u.status==='blocked'?'blocked':''}">${safe(u.status)}</span></td><td><button class="ghost-button" data-user-status="${safe(u.id)}" data-next-status="${u.status==='blocked'?'active':'blocked'}">${u.status==='blocked'?'Unblock':'Block'}</button></td></tr>`).join('')}</tbody></table></div>`;
case'categories':return `${adminHeading('Categories','Organize apps so people can find them.') }<div class="admin-panel"><h2>Store categories</h2><form id="categoryForm" style="display:flex;gap:8px;margin-bottom:14px"><input class="admin-search" name="name" required placeholder="New category name"><button class="small-button">＋ Add category</button></form>${d.categories.filter(c=>c!=='All').map(c=>`<div class="category-manage"><span>${icons[c]||icons.All} &nbsp;${safe(c)}</span><button data-delete-category="${safe(c)}">Remove</button></div>`).join('')}</div>`;
case'reviews':return `${adminHeading('Reviews','Keep the app catalogue helpful and respectful.')}<div class="admin-panel"><h2>Community feedback · ${d.reviews.length}</h2>${d.reviews.slice().reverse().map(r=>`<div class="review" style="display:flex;justify-content:space-between;gap:10px"><div><div class="review-head"><b>${safe(r.user)} · ${safe(d.apps.find(a=>a.id===r.appId)?.name||'App')}</b><span>${'★'.repeat(r.rating)}</span></div><p>${safe(r.text)} &nbsp; <span style="color:#9aa8ac">${safe(r.date)}</span></p></div><button class="ghost-button" data-delete-review="${safe(r.id)}" data-review-app="${safe(r.appId)}">Remove</button></div>`).join('')||'<div class="admin-empty">No reviews to review yet.</div>'}</div>`;
case'messages':return `${adminHeading('Announcements','Send a note to everyone using ZUStore.')}<div class="admin-panel"><h2>New announcement</h2><form id="announceForm" class="modal-form"><div class="field"><label>Message for the community</label><textarea name="text" required maxlength="500" placeholder="Share a launch, store update or helpful note…"></textarea></div><button class="small-button" style="align-self:start">Send announcement</button></form></div><div class="admin-panel"><h2>Recent announcements</h2>${d.messages.filter(m=>m.kind==='announcement').slice().reverse().map(m=>`<div class="message-card"><div class="message-avatar">✦</div><div class="message-main"><header><b>${safe(m.from)}</b><time>${safe(m.date)}</time></header><p>${safe(m.text)}</p></div></div>`).join('')||'<div class="admin-empty">No announcements yet.</div>'}</div>`;
case'settings':return `${adminHeading('Store settings','Control how ZUStore and developer submissions work.') }<div class="admin-panel"><h2>Store configuration</h2><div class="settings-row"><div><b>Accept new app submissions</b><span>Developers can send apps for review.</span></div><button class="switch ${d.settings.allowSubmissions?'on':''}" data-toggle-setting="allowSubmissions" aria-label="Toggle submissions"></button></div><div class="settings-row"><div><b>Maintenance mode</b><span>Show a maintenance notice on the store.</span></div><button class="switch ${d.settings.maintenance?'on':''}" data-toggle-setting="maintenance" aria-label="Toggle maintenance"></button></div><div class="settings-row"><div><b>Store name</b><span>${safe(d.settings.name)}</span></div><span class="status-pill">ACTIVE</span></div><div class="settings-row"><div><b>Store tagline</b><span>${safe(d.settings.tagline)}</span></div><span class="status-pill">LIVE</span></div></div>`;
default:return `<div class="admin-empty">Choose a section to manage.</div>`}}
function appTableRow(a,review){return `<tr><td><div class="table-title">${icon(a,'mini-icon')}<div>${safe(a.name)}${a.featured?'<br><span style="color:#c28d36;font-size:8px">✦ Featured</span>':''}</div></div></td><td>${safe(a.developer)}<br><span style="color:#97a4a8;font-size:8px">${safe(a.category)}</span></td><td><span class="status-pill ${a.status==='pending'?'pending':a.status==='rejected'?'blocked':''}">${safe(a.status)}</span></td><td>${Number(a.downloads||0).toLocaleString()}</td><td><div class="table-actions">${review?`<button class="approve" data-review-app="${safe(a.id)}" data-next="published">Approve</button><button class="reject" data-review-app="${safe(a.id)}" data-next="rejected">Reject</button>`:`<button data-feature-app="${safe(a.id)}">${a.featured?'Unfeature':'Feature'}</button><button data-review-app="${safe(a.id)}" data-next="rejected">Hide</button>`}</div></td></tr>`}
async function loadAdmin(){if(!state.user||state.user.role!=='admin'){authModal('login');return}const d=await api('/api/admin/overview');state.adminData=d;state.page='admin';render()}

document.addEventListener('input',e=>{if(e.target.name==='description'){const counter=document.querySelector('[data-char-count="description"]');if(counter)counter.textContent=e.target.value.length}});
document.addEventListener('change',e=>{const input=e.target;if(input.id==='adminIconFile'){const file=input.files?.[0],preview=$('#adminIconPreview');if(file&&preview){if(file.size>12*1024*1024){toast('App icon must be 12 MB or smaller.');input.value='';preview.innerHTML='';return}preview.innerHTML=`<img src="${URL.createObjectURL(file)}" alt="Icon preview"><span>${safe(file.name)}</span>`}}if(input.id==='adminApkFile'){const file=input.files?.[0],preview=$('#adminApkPreview'),size=$('#adminAppSize');if(file&&preview){if(file.size>350*1024*1024){toast('APK must be 350 MB or smaller.');input.value='';preview.textContent='No APK selected';return}preview.innerHTML=`<b>${safe(file.name)}</b><span>${formatFileSize(file.size)}</span>`;if(size&&!size.value)size.value=formatFileSize(file.size)}}if(input.id==='adminScreenshots'){const files=[...(input.files||[])],preview=$('#adminScreenshotPreviews');if(!preview)return;if(files.length>8){toast('Choose up to 8 screenshots.');input.value='';preview.innerHTML='';return}if(files.some(f=>f.size>12*1024*1024)){toast('Each screenshot must be 12 MB or smaller.');input.value='';preview.innerHTML='';return}preview.innerHTML=files.map(file=>`<div class="admin-shot-preview"><img src="${URL.createObjectURL(file)}" alt=""><span>${safe(file.name)}</span></div>`).join('')}});

document.addEventListener('click',async e=>{const target=e.target.closest('button,[data-app],[data-go],[data-category],[data-remove],[data-install],[data-submit-app],[data-admin-add-app],[data-save-library],[data-auth],[data-admin],[data-settings],[data-admin-tab],[data-msg-tab],[data-review-app],[data-feature-app],[data-user-status],[data-delete-category],[data-delete-review],[data-toggle-setting],[data-refresh-admin],[data-share],[data-carousel-next]');if(!target)return;try{
if(target.dataset.close!==undefined){closeModal();return}if(target.dataset.page){if(target.dataset.page==='games'){state.page='apps';state.category='Games'}else{state.page=target.dataset.page;state.category='All'}state.query='';render();window.scrollTo({top:0,behavior:'smooth'});return}if(target.dataset.carouselNext){const track=document.getElementById(target.dataset.carouselNext);track?.scrollBy({left:track.clientWidth*.78,behavior:'smooth'});return}if(target.dataset.go){state.page=target.dataset.go;state.category='All';state.query='';render();return}if(target.dataset.category){state.category=target.dataset.category;state.page='apps';render();return}if(target.dataset.clear!==undefined){state.query='';state.category='All';render();return}if(target.dataset.app){detailModal(target.dataset.app);return}if(target.dataset.auth){authModal(target.dataset.auth);return}if(target.dataset.submitApp!==undefined){appSubmitModal();return}if(target.dataset.adminAddApp!==undefined){adminAppModal();return}if(target.dataset.admin!==undefined){await loadAdmin();return}if(target.dataset.settings!==undefined){openModal(`<h2>Settings</h2><p class="modal-lead">Make ZUStore feel like yours.</p><div class="settings-row"><div><b>Look & feel</b><span>Light theme · Aqua and cloud</span></div><span class="status-pill">LIGHT</span></div><div class="settings-row"><div><b>Notifications</b><span>New app and developer updates</span></div><button class="switch on"></button></div><div class="settings-row"><div><b>About ZUStore</b><span>Safe · Fast · Independent</span></div><span>v1.0.0</span></div>`);return}if(target.dataset.msgTab){state.messageTab=target.dataset.msgTab;render();return}if(target.dataset.remove){await api(`/api/library/${target.dataset.remove}`,{method:'DELETE'});await refresh();toast('Removed from My Library');render();return}if(target.dataset.saveLibrary){if(!state.user){closeModal();authModal('login');return}await api('/api/apps/'+encodeURIComponent(target.dataset.saveLibrary)+'/library',{method:'POST',body:'{}'});await refresh();detailModal(target.dataset.saveLibrary);toast('Saved to My Library');return}if(target.dataset.install){const app=state.apps.find(a=>a.id===target.dataset.install);if(!app?.apkUrl){toast('APK has not been uploaded for this listing yet.');return}await api('/api/apps/'+encodeURIComponent(app.id)+'/download',{method:'POST',body:'{}'});await refresh();const link=document.createElement('a');link.href=new URL(app.apkUrl,location.href).href;link.download=app.apkName||'';document.body.appendChild(link);link.click();link.remove();detailModal(app.id);toast('APK download started');return}if(target.dataset.adminTab){state.adminTab=target.dataset.adminTab;render();return}if(target.dataset.refreshAdmin){state.adminData=await api('/api/admin/overview');render();return}if(target.dataset.reviewApp){await api('/api/admin/apps',{method:'PATCH',body:JSON.stringify({id:target.dataset.reviewApp,status:target.dataset.next})});state.adminData=await api('/api/admin/overview');render();toast(target.dataset.next==='published'?'App approved and published':'App status updated');return}if(target.dataset.featureApp){const a=state.adminData.apps.find(a=>a.id===target.dataset.featureApp);await api('/api/admin/apps',{method:'PATCH',body:JSON.stringify({id:a.id,featured:!a.featured})});state.adminData=await api('/api/admin/overview');render();toast(a.featured?'Removed from spotlight':'Added to spotlight');return}if(target.dataset.userStatus){await api('/api/admin/users',{method:'PATCH',body:JSON.stringify({id:target.dataset.userStatus,status:target.dataset.nextStatus})});state.adminData=await api('/api/admin/overview');render();toast('Account status updated');return}if(target.dataset.deleteCategory){if(confirm(`Remove ${target.dataset.deleteCategory} category?`)){await api('/api/admin/categories',{method:'DELETE',body:JSON.stringify({name:target.dataset.deleteCategory})});state.adminData=await api('/api/admin/overview');state.categories=state.adminData.categories;render()}return}if(target.dataset.deleteReview){await api('/api/admin/reviews',{method:'DELETE',body:JSON.stringify({id:target.dataset.deleteReview,appId:target.dataset.reviewApp})});state.adminData=await api('/api/admin/overview');render();toast('Review removed');return}if(target.dataset.toggleSetting){const key=target.dataset.toggleSetting;const settings={...state.adminData.settings,[key]:!state.adminData.settings[key]};await api('/api/admin/settings',{method:'PATCH',body:JSON.stringify(settings)});state.adminData=await api('/api/admin/overview');state.settings=state.adminData.settings;render();toast('Store setting updated');return}if(target.dataset.share){await navigator.clipboard?.writeText(location.origin+`/#app/${target.dataset.share}`);toast('App link copied');return}
}catch(err){toast(err.message)}});

document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;try{if(f.id==='authForm'){const data=Object.fromEntries(new FormData(f));const register=!!data.name;const res=await api(`/api/auth/${register?'register':'login'}`,{method:'POST',body:JSON.stringify(data)});state.token=res.token;localStorage.setItem('zustore-token',state.token);await refresh();closeModal();render();toast(`Welcome${register?' to ZUStore':''}, ${state.user.name.split(' ')[0]}`);if(location.pathname==='/admin')loadAdmin();return}if(f.id==='appSubmitForm'){const fd=new FormData(f);let apkUrl='',apkName='',iconUrl='';const file=fd.get('apk'),iconFile=fd.get('iconFile');if(file?.size){const up=await uploadFile(file);apkUrl=up;apkName=file.name}if(iconFile?.size)iconUrl=await uploadFile(iconFile);const screenshots=[];for(const shot of fd.getAll('screenshots')){if(shot?.size)screenshots.push({name:shot.name,url:await uploadFile(shot)})}await api('/api/apps',{method:'POST',body:JSON.stringify({name:fd.get('name'),category:fd.get('category'),version:fd.get('version'),size:fd.get('size')||'—',description:fd.get('description'),iconUrl,apkUrl,apkName,screenshots})});await refresh();closeModal();state.page='profile';render();toast('Your app is in the review queue');return}if(f.id==='adminAppForm'){const fd=new FormData(f),apkFile=fd.get('apk'),iconFile=fd.get('iconFile'),shotFiles=[...fd.getAll('screenshots')].filter(x=>x?.size);if(!apkFile?.size||!iconFile?.size)throw new Error('Choose both an APK and an app icon.');if(!apkFile.name.toLowerCase().endsWith('.apk'))throw new Error('Choose a valid .apk package.');if(apkFile.size>350*1024*1024)throw new Error('APK must be 350 MB or smaller.');if(iconFile.size>12*1024*1024||shotFiles.some(x=>x.size>12*1024*1024))throw new Error('Each image must be 12 MB or smaller.');if(shotFiles.length>8)throw new Error('Choose up to 8 screenshots.');const progress=$('#adminUploadProgress'),bar=$('#adminUploadBar'),status=$('#adminUploadStatus'),submit=$('#adminAppSubmit');progress.hidden=false;submit.disabled=true;let completed=0,totalFiles=2+shotFiles.length;const upload=async(file,label)=>{status.textContent=`${label}: ${file.name}`;return uploadFile(file,(loaded,total)=>{const percent=Math.round(((completed+loaded/total)/totalFiles)*100);bar.style.width=`${percent}%`;status.textContent=`${label}: ${file.name} · ${percent}%`})};try{const iconUrl=await upload(iconFile,'Uploading icon');completed++;bar.style.width=`${Math.round(completed/totalFiles*100)}%`;const apkUrl=await upload(apkFile,'Uploading APK');completed++;const screenshots=[];for(const shot of shotFiles){const url=await upload(shot,'Uploading screenshot');screenshots.push({name:shot.name.replace(/\.[^.]+$/,''),url});completed++;bar.style.width=`${Math.round(completed/totalFiles*100)}%`}const tags=String(fd.get('tags')||'').split(',').map(t=>t.trim()).filter(Boolean).slice(0,12);status.textContent='Saving store listing…';await api('/api/admin/apps',{method:'POST',body:JSON.stringify({name:fd.get('name'),developer:fd.get('developer'),category:fd.get('category'),subcategory:fd.get('subcategory'),version:fd.get('version'),versionCode:fd.get('versionCode')||'',packageName:fd.get('packageName'),minAndroid:fd.get('minAndroid'),size:fd.get('size')||formatFileSize(apkFile.size),description:fd.get('description'),fullDescription:fd.get('fullDescription'),whatsNew:fd.get('whatsNew'),contentRating:fd.get('contentRating'),websiteUrl:fd.get('websiteUrl'),supportEmail:fd.get('supportEmail'),privacyUrl:fd.get('privacyUrl'),tags,iconUrl,apkUrl,apkName:apkFile.name,screenshots,status:fd.get('status'),badge:fd.get('badge'),featured:fd.get('featured')==='on'})});await refresh();state.adminData=await api('/api/admin/overview');closeModal();state.page='admin';state.adminTab='apps';render();toast(fd.get('status')==='published'?'App published with APK':'App saved for review')}finally{submit.disabled=false}return}if(f.id==='reviewForm'){const appId=f.dataset.reviewAppId;const fd=new FormData(f);if(!appId)return;await api(`/api/apps/${appId}/reviews`,{method:'POST',body:JSON.stringify({rating:fd.get('rating'),text:fd.get('text')})});await refresh();detailModal(appId);toast('Thanks for your review');return}if(f.id==='messageForm'){const fd=new FormData(f);await api('/api/messages',{method:'POST',body:JSON.stringify({text:fd.get('text')})});await refresh();render();toast('Message sent to the community');return}if(f.id==='categoryForm'){const fd=new FormData(f);await api('/api/admin/categories',{method:'POST',body:JSON.stringify({name:fd.get('name')})});state.adminData=await api('/api/admin/overview');state.categories=state.adminData.categories;render();toast('Category added');return}if(f.id==='announceForm'){const fd=new FormData(f);await api('/api/admin/messages',{method:'POST',body:JSON.stringify({text:fd.get('text')})});state.adminData=await api('/api/admin/overview');render();toast('Announcement sent');return}}catch(err){toast(err.message)}});


$('#searchInput').addEventListener('input',e=>{state.query=e.target.value;state.page='apps';render();$('#searchInput').focus();$('#searchInput').setSelectionRange(state.query.length,state.query.length)});
$('#clearSearch').addEventListener('click',()=>{state.query='';render();$('#searchInput').focus()});
$('#mobileSearch').addEventListener('click',()=>{window.scrollTo({top:0,behavior:'smooth'});$('#searchInput').focus()});
$('#accountBtn').addEventListener('click',()=>{state.page='profile';render()});
$('#notificationsBtn').addEventListener('click',()=>{state.page='messages';render()});
$('#settingsBtn').addEventListener('click',()=>$('#mainContent').dispatchEvent(new CustomEvent('openSettings')));
$('#mainContent').addEventListener('openSettings',()=>openModal(`<h2>Settings</h2><p class="modal-lead">Make ZUStore feel like yours.</p><div class="settings-row"><div><b>Look & feel</b><span>Light theme · Aqua and cloud</span></div><span class="status-pill">LIGHT</span></div><div class="settings-row"><div><b>Notifications</b><span>App and developer updates</span></div><span class="status-pill">ON</span></div><div class="settings-row"><div><b>About ZUStore</b><span>Safe · Fast · Independent</span></div><span>v1.0.0</span></div>`));
$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#searchInput').focus()}});
document.addEventListener('change',e=>{const role=e.target.closest('[data-user-role]');if(role){api('/api/admin/users',{method:'PATCH',body:JSON.stringify({id:role.dataset.userRole,role:role.value})}).then(async()=>{state.adminData=await api('/api/admin/overview');toast('User role updated')}).catch(err=>toast(err.message))}});
document.addEventListener('click',e=>{const logout=e.target.closest('#logoutBtn');if(logout){api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.token='';state.user=null;localStorage.removeItem('zustore-token');state.page='profile';render();toast('You are signed out');}const search=e.target.closest('#userSearch');if(search){/* input handler below */}});
document.addEventListener('input',e=>{if(e.target.id==='userSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-user-row]').forEach(row=>row.hidden=!row.dataset.userRow.includes(q))}if(e.target.id==='appStatusFilter'){document.querySelectorAll('[data-review-app]').forEach(()=>{});const q=e.target.value;document.querySelectorAll('.admin-table tbody tr').forEach((row,i)=>{const a=state.adminData?.apps[i];row.hidden=q!=='all'&&a?.status!==q})}});

(async()=>{try{await refresh()}catch(e){console.error(e)}if(location.pathname==='/admin'){await loadAdmin().catch(()=>{state.page='admin';render()})}else{const hash=location.hash;if(hash.startsWith('#app/'))setTimeout(()=>detailModal(hash.split('/')[1]),100);render()}if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('/sw.js').catch(()=>{})})();
